using System.Net;
using System.Text.RegularExpressions;
using DanaProcessing.Ide.Compilation;
using Xunit;

namespace DanaProcessing.Tests.Ide;

/// <summary>
/// The website (index.html + reference/*.html, generated by site/build.py):
/// every "Run in Dana" example compiles, every link and anchor lands on
/// something, old one-page links still find their page, and every page keeps
/// the accessibility basics (one h1, a skip link, a main landmark, code
/// blocks the keyboard can reach).
/// </summary>
public class DocsExamplesTests
{
    /// <summary>The repo root (the folder with index.html and reference/), found by walking up from the test binaries; null outside a checkout.</summary>
    internal static string? FindSiteRoot()
    {
        for (var dir = new DirectoryInfo(AppContext.BaseDirectory); dir != null; dir = dir.Parent)
        {
            if (File.Exists(Path.Combine(dir.FullName, "index.html")) && Directory.Exists(Path.Combine(dir.FullName, "reference")))
                return dir.FullName;
        }
        return null;
    }

    /// <summary>Every page of the site, as (path relative to the root with '/', html).</summary>
    internal static List<(string Path, string Html)> Pages(string root)
    {
        var pages = new List<(string, string)> { ("index.html", File.ReadAllText(Path.Combine(root, "index.html"))) };
        foreach (var file in Directory.GetFiles(Path.Combine(root, "reference"), "*.html").OrderBy(f => f, StringComparer.Ordinal))
            pages.Add(("reference/" + Path.GetFileName(file), File.ReadAllText(file)));
        return pages;
    }

    /// <summary>(id, source) of every pre that a "Run in Dana" button runs, with the highlighting stripped -- what the button sends to the IDE.</summary>
    internal static List<(string Id, string Code)> Extract(string html)
    {
        var result = new List<(string, string)>();
        foreach (Match b in Regex.Matches(html, "<button class=\"dana-test-btn\" data-target=\"([^\"]+)\""))
        {
            string id = b.Groups[1].Value;
            var pre = Regex.Match(html, "<pre[^>]*\\bid=\"" + Regex.Escape(id) + "\"[^>]*>(.*?)</pre>", RegexOptions.Singleline);
            Assert.True(pre.Success, $"button for '{id}' has no <pre id=\"{id}\">");
            result.Add((id, WebUtility.HtmlDecode(Regex.Replace(pre.Groups[1].Value, "<[^>]+>", ""))));
        }
        return result;
    }

    private static List<(string Page, string Id, string Code)> AllExamples(string root) =>
        Pages(root).SelectMany(p => Extract(p.Html).Select(e => (p.Path, e.Id, e.Code))).ToList();

    private static HashSet<string> IdsOf(string html) =>
        Regex.Matches(html, "\\bid=\"([^\"]+)\"").Select(m => m.Groups[1].Value).ToHashSet();

    [Fact]
    public void The_docs_have_a_runnable_example_per_section()
    {
        var root = FindSiteRoot();
        if (root == null)
            return; // not running from a checkout
        var examples = AllExamples(root);
        Assert.True(examples.Count >= 34, $"only {examples.Count} runnable examples");
        Assert.Contains(examples, e => e.Id == "tutorial-6-code" && e.Page == "reference/tutorial.html");
        Assert.Contains(examples, e => e.Id == "from-processing-code");
        // A sketch, or an attached one (it draws on another window: see attached.html).
        Assert.All(examples, e => Assert.Matches(": (Attached)?Sketch\\b", e.Code));
        Assert.Contains(examples, e => e.Id == "attached-example-code" && e.Page == "reference/attached.html");
        Assert.Equal(examples.Count, examples.Select(e => e.Id).Distinct().Count());
    }

    [Fact]
    public void Docs_examples_compile()
    {
        var root = FindSiteRoot();
        if (root == null)
            return;
        var failures = new List<string>();
        foreach (var (page, id, code) in AllExamples(root))
        {
            var r = SketchCompiler.Compile(code);
            if (!r.Success)
                failures.Add($"{page} {id}: " + string.Join(" | ", r.Errors.Take(3)));
        }
        Assert.True(failures.Count == 0, string.Join("\n", failures));
    }

    [Fact]
    public void The_live_generative_and_day_to_day_pages_have_examples()
    {
        var root = FindSiteRoot();
        if (root == null)
            return;
        var pages = Pages(root).ToDictionary(p => p.Path, p => p.Html);
        var expected = new Dictionary<string, string[]>
        {
            ["reference/live.html"] = new[] { "midi", "beat", "listento", "performance-mode", "live-example-code", "midi-example-code" },
            ["reference/generative.html"] = new[] { "seed", "variations", "print-export", "generative-example-code", "plotter-example-code" },
            ["reference/workflow.html"] = new[] { "stats", "data-folder", "rewind", "time-machine", "workflow-example-code", "stats-example-code" },
        };
        foreach (var (page, ids) in expected)
        {
            Assert.True(pages.ContainsKey(page), page + " is missing");
            var have = IdsOf(pages[page]);
            Assert.All(ids, id => Assert.True(have.Contains(id), $"{page} has no #{id}"));
        }
    }

    [Fact]
    public void Every_link_and_anchor_points_at_something_on_the_site()
    {
        var root = FindSiteRoot();
        if (root == null)
            return;
        var pages = Pages(root);
        var ids = pages.ToDictionary(p => p.Path, p => IdsOf(p.Html));
        var broken = new List<string>();
        foreach (var (path, html) in pages)
        {
            var dir = Path.GetDirectoryName(path)!.Replace('\\', '/');
            foreach (Match m in Regex.Matches(html, "<a\\b[^>]*\\bhref=\"([^\"]+)\""))
            {
                var href = WebUtility.HtmlDecode(m.Groups[1].Value);
                if (Regex.IsMatch(href, "^(https?:|mailto:|danaide:)"))
                    continue;
                var parts = href.Split('#', 2);
                string target = path;
                if (parts[0].Length > 0)
                {
                    var file = Path.GetFullPath(Path.Combine(root, dir, parts[0]));
                    if (!File.Exists(file))
                    {
                        broken.Add($"{path}: {href} (no such file)");
                        continue;
                    }
                    target = Path.GetRelativePath(root, file).Replace('\\', '/');
                }
                if (parts.Length == 2 && parts[1].Length > 0 && ids.TryGetValue(target, out var targetIds) && !targetIds.Contains(parts[1]))
                    broken.Add($"{path}: {href} (no #{parts[1]} there)");
            }
        }
        Assert.True(broken.Count == 0, string.Join("\n", broken.Take(30)));
    }

    [Fact]
    public void Old_one_page_links_find_their_new_page()
    {
        var root = FindSiteRoot();
        if (root == null)
            return;
        var anchors = File.ReadAllText(Path.Combine(root, "assets", "anchors.js"));
        Assert.Contains("\"fill\":\"reference/color.html#fill\"", anchors);
        Assert.Contains("\"color\":\"reference/color.html\"", anchors);
        Assert.Contains("\"midi\":\"reference/live.html#midi\"", anchors);
        Assert.Contains("assets/anchors.js", File.ReadAllText(Path.Combine(root, "index.html")));
    }

    [Fact]
    public void Every_page_keeps_the_accessibility_basics()
    {
        var root = FindSiteRoot();
        if (root == null)
            return;
        foreach (var (path, html) in Pages(root))
        {
            Assert.Contains("<html lang=\"en\"", html);
            Assert.Equal(1, Regex.Matches(html, "<h1[\\s>]").Count);
            Assert.Contains("class=\"skip\" href=\"#main\"", html);
            Assert.Contains("<main id=\"main\"", html);
            Assert.Contains("<meta name=\"viewport\"", html);
            foreach (Match pre in Regex.Matches(html, "<pre[^>]*>"))
                Assert.True(pre.Value.Contains("tabindex=\"0\""), $"{path}: a code block the keyboard can't reach: {pre.Value}");
            foreach (Match svg in Regex.Matches(html, "<svg[^>]*>"))
                Assert.True(svg.Value.Contains("aria-hidden=\"true\"") || svg.Value.Contains("aria-label="), $"{path}: an svg with no name that isn't hidden: {svg.Value}");
            Assert.DoesNotContain("data-mode-section", html); // no content hidden behind a 2D/3D/Sound mode any more
        }
    }
}
